import{_ as r,C as n,o as d,c as l,a6 as s,E as a,j as t,a as o}from"./chunks/framework.CMg4qq8Q.js";const b=JSON.parse('{"title":"Web Cache Deception","description":"Path mapping, delimiters, origin and cache normalisation, and exact-match cache rules.","frontmatter":{"title":"Web Cache Deception","description":"Path mapping, delimiters, origin and cache normalisation, and exact-match cache rules."},"headers":[],"relativePath":"cache-deception/index.md","filePath":"cache-deception/index.md"}'),h={name:"cache-deception/index.md"};function p(u,e,g,m,v,f){const i=n("LabGroup"),c=n("TopicComplete");return d(),l("div",null,[e[0]||(e[0]=s('<h1 id="web-cache-deception-·-the-leaked-dossier" tabindex="-1">Web Cache Deception · The Leaked Dossier <a class="header-anchor" href="#web-cache-deception-·-the-leaked-dossier" aria-label="Permalink to &quot;Web Cache Deception · The Leaked Dossier&quot;">​</a></h1><p class="wd-section-lede">Web cache deception is the mirror image of cache poisoning. While poisoning forces the cache to store malicious attacker content for everyone else to consume, deception tricks the cache into saving an innocent victim&#39;s <em>private personal data</em> as if it were a public file—letting the attacker casually download it moments later.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Envelope with the Wrong Label.</strong> Imagine walking into a bank to collect your confidential financial statement. A prankster convinces you to place the envelope inside a clear plastic sleeve labeled <code>PUBLIC_PROMOTIONAL_FLYER.png</code>. The bank teller verifies your ID, places your confidential financial statement inside the sleeve, and hands it to you. But as you pass through the lobby, the front-desk security guard spots the label <code>PUBLIC_PROMOTIONAL_FLYER.png</code>, makes a photocopy of everything inside, and pins it directly to the public bulletin board. Five minutes later, the prankster walks into the lobby and reads your financial records right off the wall.</p></div><h2 id="case-file-3-the-anatomy-of-a-deceptive-cache" tabindex="-1">Case File #3: The Anatomy of a Deceptive Cache <a class="header-anchor" href="#case-file-3-the-anatomy-of-a-deceptive-cache" aria-label="Permalink to &quot;Case File #3: The Anatomy of a Deceptive Cache&quot;">​</a></h2><p>Web cache deception thrives on a fundamental disagreement between two systems: the edge cache inspects the <strong>file extension</strong> to decide if an asset is public, while the backend origin inspects the <strong>route prefix</strong> to decide which private data to serve.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>A logged-in victim receives a link from an attacker: <code>https://example.com/my-account/avatar.css</code>. When clicked, the victim&#39;s browser sends their session cookies. The page renders their private profile information or a seemingly blank stylesheet.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend application framework uses permissive routing (or path rewriting). It spots <code>/my-account</code>, ignores the trailing <code>/avatar.css</code>, and renders the victim&#39;s confidential account dashboard containing their private API keys and email address.</p></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>As the response streams back through the edge CDN, the caching engine evaluates the URL. Because the path ends with <code>.css</code>, and the response lacks strict <code>no-store</code> headers, the CDN assumes it is a static stylesheet and saves the entire private HTML page in public edge storage!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Always send <code>Cache-Control: private, no-store</code> on all authenticated endpoints, configure cache rules to obey response headers rather than file extensions, and ensure origin routing strictly returns 404 for extraneous path suffixes.</p></div></div><h3 id="visual-comparison-static-expectation-vs-dynamic-reality" tabindex="-1">Visual Comparison: Static Expectation vs. Dynamic Reality <a class="header-anchor" href="#visual-comparison-static-expectation-vs-dynamic-reality" aria-label="Permalink to &quot;Visual Comparison: Static Expectation vs. Dynamic Reality&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The CDN only caches static files like stylesheets, scripts, and logos. Sensitive account pages are dynamic and will never be saved to shared public storage.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The origin ignored the trailing filename and served private profile data. The CDN keyed the response under <code>/avatar.css</code> and cached the private data, allowing an unauthenticated attacker to view it.</p></div></div><h3 id="splitting-the-route-the-deceptive-url" tabindex="-1">Splitting the Route: The Deceptive URL <a class="header-anchor" href="#splitting-the-route-the-deceptive-url" aria-label="Permalink to &quot;Splitting the Route: The Deceptive URL&quot;">​</a></h3><p>Look at how the two layers read the exact same path differently:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Dynamic Private Route (Read by Backend Origin)</span><span><span class="wd-code-input">Gold</span> = Deceptive Static Suffix (Read by Edge Cache)</span></div><span class="wd-code-dev">https://example.com/my-account</span><span class="wd-code-input">/avatar.css</span></div><details class="details custom-block"><summary>🔬 Under the Hood: The Three Iron Rules for Web Cache Deception</summary><p>For an attacker to successfully steal private user information through cache deception, three separate conditions must all be met simultaneously:</p><ol><li><strong>The Cache Must Rely on File Extensions:</strong> The edge CDN must judge whether a file is cacheable by looking at its URL suffix (e.g., <code>.css</code>, <code>.js</code>, <code>.jpg</code>) rather than the origin&#39;s <code>Content-Type</code> header.</li><li><strong>The Origin Must Forgive Extraneous Path Segments:</strong> The web framework must strip or ignore arbitrary suffixes (via wildcard routing, <code>PATH_INFO</code>, or trailing-slash rewrites) and still render the private account data.</li><li><strong>The Victim Must Be Authenticated:</strong> The victim must click the crafted link while holding an active session cookie on the target website.</li></ol></details><hr><h2 id="the-5-stage-life-of-a-cache-deception-attack" tabindex="-1">The 5-Stage Life of a Cache Deception Attack <a class="header-anchor" href="#the-5-stage-life-of-a-cache-deception-attack" aria-label="Permalink to &quot;The 5-Stage Life of a Cache Deception Attack&quot;">​</a></h2><p>Follow the path of a victim&#39;s private profile as it lands on a public CDN edge:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Lure Delivery</strong> Attacker crafts a link appending a static extension to a private route (<code>/profile/w.js</code>). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Victim Click</strong> Logged-in victim clicks the lure; browser automatically attaches session cookies. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Permissive Origin</strong> Origin ignores <code>/w.js</code>, renders the victim&#39;s private profile, omitting <code>no-store</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Public Caching</strong> Edge CDN sees <code>.js</code>, stores the private profile body in its shared cache. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Unauthenticated Harvest</strong> Attacker browses to <code>/profile/w.js</code> with no cookies and reads the cached profile! </div></div><hr><h2 id="path-mapping-vulnerabilities" tabindex="-1">Path Mapping Vulnerabilities <a class="header-anchor" href="#path-mapping-vulnerabilities" aria-label="Permalink to &quot;Path Mapping Vulnerabilities&quot;">​</a></h2><p>The most direct form of cache deception relies on URL path mapping. Many web server frameworks (such as Django, Spring, or PHP) route requests by matching path prefixes.</p><p>When a request for <code>/my-account/nonexistent.jpg</code> arrives, the routing dispatcher matches the prefix <code>/my-account</code>, invokes the account controller, and returns the victim&#39;s profile page with HTTP status 200 OK. The caching layer sees <code>.jpg</code> and caches the response.</p>',20)),a(i,{ids:"cache-deception-lab-wcd-exploiting-path-mapping"}),e[1]||(e[1]=s('<hr><h2 id="delimiters-semicolons-hashes-and-dots" tabindex="-1">Delimiters: Semicolons, Hashes, and Dots <a class="header-anchor" href="#delimiters-semicolons-hashes-and-dots" aria-label="Permalink to &quot;Delimiters: Semicolons, Hashes, and Dots&quot;">​</a></h2><p>When simple path appending fails, attackers turn to delimiter characters to confuse the boundary between the route and the filename.</p><p>Different web technologies recognize different characters as path separators:</p><ul><li><strong>Semicolons (<code>;</code>):</strong> Java Spring and matrix parameter implementations treat everything after a semicolon as parameter data, routing <code>/my-account;param.css</code> directly to <code>/my-account</code>. Meanwhile, the CDN sees a file ending in <code>.css</code>.</li><li><strong>Question Marks (<code>?</code>) and Hashes (<code>#</code>):</strong> If the cache or origin fails to decode encoded delimiters (<code>%23</code>, <code>%3F</code>), one server sees a query parameter while the other sees part of the file path.</li><li><strong>Null Bytes (<code>%00</code>):</strong> In legacy systems, null bytes terminate strings prematurely on the origin while the cache processes the full URL.</li></ul>',5)),a(i,{ids:"cache-deception-lab-wcd-exploiting-path-delimiters"}),e[2]||(e[2]=s('<details class="details custom-block"><summary>🔬 Under the Hood: How Path Normalization Creates Deception</summary><p>Web servers and CDNs regularly &quot;normalize&quot; incoming paths to resolve relative jumps:</p><ul><li>Collapsing double slashes (<code>//my-account</code> → <code>/my-account</code>)</li><li>Resolving dot segments (<code>/my-account/../my-account</code>)</li><li>Decoding percent-encoded characters (<code>%2e%2e%2f</code> → <code>../</code>)</li></ul><p>A critical vulnerability occurs when the cache and origin perform this normalization in <strong>different orders</strong>. If the cache keys the raw URL while the origin decodes dot segments, an attacker can craft <code>/my-account%2f..%2fstatic.css</code>. The origin normalizes and serves <code>/my-account</code>, but the cache indexes the request as a static stylesheet!</p></details><hr><h2 id="origin-vs-cache-normalization" tabindex="-1">Origin vs. Cache Normalization <a class="header-anchor" href="#origin-vs-cache-normalization" aria-label="Permalink to &quot;Origin vs. Cache Normalization&quot;">​</a></h2><p>The two labs below test the direction of path normalization discrepancies:</p><ul><li><strong>Origin Server Normalization:</strong> The origin resolves directory traversal dot-segments (<code>/..</code>), collapsing the path back to the private route, while the cache stores the response based on the raw un-normalized static string.</li><li><strong>Cache Server Normalization:</strong> The cache resolves dot-segments and determines that the URL targets a static file path, while the backend application routes on the raw un-normalized path.</li></ul>',5)),a(i,{ids:"cache-deception-lab-wcd-exploiting-origin-server-normalization, cache-deception-lab-wcd-exploiting-cache-server-normalization"}),e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"exact-match-cache-rules",tabindex:"-1"},[o("Exact-Match Cache Rules "),t("a",{class:"header-anchor",href:"#exact-match-cache-rules","aria-label":'Permalink to "Exact-Match Cache Rules"'},"​")],-1)),e[5]||(e[5]=t("p",null,[o("Many modern enterprise CDNs avoid broad wildcard extension rules and instead use precise matching rules (e.g., only caching paths matching "),t("code",null,"/static/*"),o(" or "),t("code",null,"/resources/*.js"),o(").")],-1)),e[6]||(e[6]=t("p",null,"To deceive an exact-match cache rule, an attacker must craft a path that satisfies the CDN's exact prefix or regex rule while tricking the origin into resolving back to a sensitive endpoint—frequently accomplished using path traversal sequences or server-specific path parameters.",-1)),a(i,{ids:"cache-deception-lab-wcd-exploiting-exact-match-cache-rules"}),e[7]||(e[7]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: Caching Behaviors Across CDNs</summary><ul><li><strong>Cloudflare:</strong> Caches standard static extensions by default (e.g., <code>.css</code>, <code>.js</code>, <code>.jpg</code>, <code>.pdf</code>). Custom Page Rules configured to &quot;Cache Everything&quot; will aggressively store HTML pages unless explicit cache headers prohibit it.</li><li><strong>Akamai:</strong> Relies heavily on Property Manager rules. Path-based caching behaviors must be explicitly synchronized with origin web server routing.</li><li><strong>Varnish Cache:</strong> Uses <code>vcl_recv</code> and <code>vcl_backend_response</code>. Unless configured to check <code>beresp.http.Cache-Control</code>, custom VCL scripts may blindly cache based on regex file extensions.</li><li><strong>Nginx <code>proxy_cache</code>:</strong> Caching behavior is configured via <code>proxy_cache_valid</code>. If set for 200 OK responses without checking origin headers, dynamic pages will be saved.</li></ul><p>The deception succeeds whenever the deployment&#39;s rule for <em>&quot;what is cacheable&quot;</em> is broader than the application&#39;s rule for <em>&quot;what is public&quot;</em>.</p></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Defensive Blueprint: How to Prevent Cache Deception</strong></p><ol><li><strong>Send Explicit Cache Directives:</strong> Every authenticated endpoint MUST return <code>Cache-Control: private, no-store, max-age=0</code>. Caches will never store responses carrying this header.</li><li><strong>Cache by Content-Type, Not Extension:</strong> Configure CDNs to cache responses based on the <code>Content-Type</code> header returned by the origin, rather than guessing from the URL file extension.</li><li><strong>Strict Origin Routing:</strong> Configure web frameworks to reject extraneous path segments (disable permissive wildcard routing on authenticated routes). A request for <code>/my-account/test.css</code> should return an instant 404.</li><li><strong>Synchronize URL Parsing:</strong> Ensure that reverse proxies and backend application servers treat delimiters (<code>;</code>, <code>?</code>, <code>#</code>) and URL encodings identically.</li></ol></div>',2)),a(c,{"topic-id":"web-cache-deception",label:"Mark web cache deception complete"})])}const y=r(h,[["render",p]]);export{b as __pageData,y as default};
